package com.gregtech.gregtech.client;
import com.gregtech.gregtech.registry.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid = com.gregtech.gregtech.api.mod.GregTechIdentity.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class BookShelfClientSetup {@SubscribeEvent public static void renderers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterRenderers e){e.registerBlockEntityRenderer(GTBlockEntities.BOOKSHELF.get(),BookShelfRenderer::new);}@SubscribeEvent public static void blocks(net.neoforged.neoforge.client.event.RegisterColorHandlersEvent.Block e){for(var b:GTBookShelves.all())e.register((s,l,p,t)->t==0&&b.get().variant().metal()?b.get().variant().material().getColor():0xFFFFFF,b.get());}@SubscribeEvent public static void items(net.neoforged.neoforge.client.event.RegisterColorHandlersEvent.Item e){for(var b:GTBookShelves.all())e.register((s,t)->t==0&&b.get().variant().metal()?b.get().variant().material().getColor():0xFFFFFF,b.get().asItem());}}
